[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectRoot,[Parameter(Mandatory=$true)][string]$GraphPath)
$ErrorActionPreference='Stop';$root=(Resolve-Path -LiteralPath $ProjectRoot).Path;if([IO.Path]::IsPathRooted($GraphPath)){throw 'GraphPath must be project-relative.'};$relative=$GraphPath.Replace('\','/').Trim();if($relative.Contains('..')-or $relative -notmatch '^ES/Output/.+\.json$'){throw 'GraphPath must remain under ES/Output.'};$full=Join-Path $root ($relative.Replace('/',[IO.Path]::DirectorySeparatorChar));if(-not(Test-Path -LiteralPath $full -PathType Leaf)){throw "Stable graph missing: $relative"};$outputRoot=(Resolve-Path (Join-Path $root 'ES\Output')).Path.TrimEnd('\','/');$resolved=(Resolve-Path $full).Path;if(-not $resolved.StartsWith("$outputRoot$([IO.Path]::DirectorySeparatorChar)",[StringComparison]::OrdinalIgnoreCase)){throw 'Resolved graph path escapes ES/Output.'};$raw=[Text.UTF8Encoding]::new($false,$true).GetString([IO.File]::ReadAllBytes($resolved));if($raw -match '(?i)(Legacy\s*GraphView|NodeRunner)'){throw 'Legacy GraphView/NodeRunner is forbidden.'};$g=$raw|ConvertFrom-Json;foreach($x in @('graphId','schemaVersion','consumer','migration','snapshot','evidenceRef','owner','staleWhen','nodes','edges')){if($null -eq $g.PSObject.Properties[$x]){throw "Missing graph field: $x"}};if([string]$g.schemaVersion -ne '2'-or @($g.nodes).Count -eq 0){throw 'Stable Graph V2 requires schemaVersion 2 and nodes.'};$ids=@{};foreach($n in @($g.nodes)){if([string]::IsNullOrWhiteSpace([string]$n.nodeId)-or [string]::IsNullOrWhiteSpace([string]$n.type)){throw 'Graph node requires nodeId and type.'};if($ids.ContainsKey([string]$n.nodeId)){throw "Duplicate node identity: $($n.nodeId)"};$ids[[string]$n.nodeId]=$true};$orders=@{};foreach($e in @($g.edges)){foreach($x in @('from','to','order')){if($null -eq $e.PSObject.Properties[$x]){throw "Graph edge missing $x."}};if(-not $ids.ContainsKey([string]$e.from)-or -not $ids.ContainsKey([string]$e.to)){throw 'Graph edge references an unknown node.'};if($orders.ContainsKey([int]$e.order)){throw "Duplicate edge order: $($e.order)"};$orders[[int]$e.order]=$true};Write-Output "PASS: Stable Graph V2 identities, ordered edges, migration and consumer snapshot are valid: $relative"
